#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, M;
    cin >> n >> M;

    vector<vector<int>> divisor_groups(n + 1);
    for (int divisor = 2; divisor <= n; ++divisor) {
        for (int multiple = 2 * divisor; multiple <= n; multiple += divisor) {
            divisor_groups[multiple].push_back(divisor);
        }
    }

    vector<long long> F(n + 1, 0);
    F[1] = 1;
    if (n >= 2) F[2] = 2;

    for (int index = 3; index <= n; ++index) {
        F[index] = (2 * F[index - 1] + F[index / (index - 1)]) % M;
        long long total_diff = 0;
        for (int d : divisor_groups[index]) {
            if (d >= 2 && d <= index - 2) {
                total_diff += F[index / d] - F[(index - 1) / d];
            }
        }
        F[index] = (F[index] + total_diff) % M;
    }

    cout << F[n] % M << "\n";

    return 0;
}
